/// Whether a policy names a role held, the action and the resource (AnyObject covers every object), its condition aside.
///
/// Specification function `policy-applies`.
pub fn policy_applies(
    policy: &types::PolicyDef,
    roles: &Vec<String>,
    action: &types::Action,
    resource: &types::Resource,
) -> bool {
    roles.iter().any(|r| *r == policy.role)
        && policy.actions.iter().any(|a| *a == *action)
        && (match &policy.resource {
            types::Resource::AnyObject => match resource {
                types::Resource::Object(_) => true,
                _ => policy.resource == *resource,
            },
            _ => policy.resource == *resource,
        })
}

