/// What the functions share: list helpers and the bridges to the languages.
mod support {
    use crate::types;

    /// The items of `a`, then those of `b`.
    pub(super) fn concat<T: Clone>(a: &[T], b: &[T]) -> Vec<T> {
        let mut out = a.to_vec();
        out.extend_from_slice(b);
        out
    }

    /// Whether a string has a character and every one passes the test (Exegra's
    /// isAscii* operations).
    pub(super) fn every_char(s: &str, test: fn(&char) -> bool) -> bool {
        !s.is_empty() && s.chars().all(|c| test(&c))
    }

    /// Exegra's parseTime, which is substrate's parse_time: `YYYY-MM-DD` or
    /// `YYYY-MM-DDTHH:MM[:SS]Z` (UTC) as milliseconds since the epoch. The date and time
    /// split at the first `T`; the year is four bytes; each number is read as
    /// `i64::from_str` reads it; month 1..=12, day 1..=31, hour 0..24, minute and
    /// second 0..60. It computes in i128, so a time beyond the i64 milliseconds is
    /// refused rather than wrapped.
    pub(super) fn parse_time(text: &str) -> Result<i64, String> {
        let bad = || format!("not a UTC timestamp: {text:?}");
        let number = |s: &str| s.parse::<i64>().map(i128::from).map_err(|_| bad());
        let (date, time) = match text.split_once('T') {
            Some((date, time)) => (date, Some(time.strip_suffix('Z').ok_or_else(bad)?)),
            None => (text, None),
        };
        let parts: Vec<&str> = date.split('-').collect();
        if parts.len() != 3 || parts[0].len() != 4 {
            return Err(bad());
        }
        let (year, month, day) = (number(parts[0])?, number(parts[1])?, number(parts[2])?);
        if !(1..=12).contains(&month) || !(1..=31).contains(&day) {
            return Err(bad());
        }
        let y = if month <= 2 { year - 1 } else { year };
        let era = if y >= 0 { y } else { y - 399 } / 400;
        let yoe = y - era * 400;
        let doy = (153 * (month + if month > 2 { -3 } else { 9 }) + 2) / 5 + day - 1;
        let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        let mut seconds = (era * 146_097 + doe - 719_468) * 86_400;
        if let Some(time) = time {
            let parts: Vec<&str> = time.split(':').collect();
            if !(2..=3).contains(&parts.len()) {
                return Err(bad());
            }
            let (hour, minute) = (number(parts[0])?, number(parts[1])?);
            let second = if parts.len() == 3 {
                number(parts[2])?
            } else {
                0
            };
            if !(0..24).contains(&hour) || !(0..60).contains(&minute) || !(0..60).contains(&second)
            {
                return Err(bad());
            }
            seconds += hour * 3_600 + minute * 60 + second;
        }
        i64::try_from(seconds * 1_000).map_err(|_| bad())
    }

    /// Exegra's snakeCase (the kernel's snake_case of a PascalCase name): every ASCII
    /// capital becomes its lower case, after a `_` unless it is the first character.
    pub(super) fn snake_case(name: &str) -> String {
        let mut out = String::new();
        for (i, c) in name.chars().enumerate() {
            if c.is_ascii_uppercase() {
                if i > 0 {
                    out.push('_');
                }
                out.push(c.to_ascii_lowercase());
            } else {
                out.push(c);
            }
        }
        out
    }

    /// The items ordered by a key, stably.
    pub(super) fn sorted_by<'a, T: Clone + 'a, K: Ord>(
        items: impl Iterator<Item = &'a T>,
        key: impl FnMut(&T) -> K,
    ) -> Vec<T> {
        let mut out: Vec<T> = items.cloned().collect();
        out.sort_by_key(key);
        out
    }

    impl crate::rule_language::Record for std::collections::BTreeMap<String, types::Value> {
        fn system_attribute(&self, name: &str) -> types::Value {
            self.get(name).cloned().unwrap_or(types::Value::Null)
        }

        fn field(&self, name: &str) -> Result<types::Value, String> {
            Ok(self.get(name).cloned().unwrap_or(types::Value::Null))
        }
    }
    pub(super) fn eval_rule_language_rule_env(
        expr: &types::Expr,
        env: &types::RuleEnv,
    ) -> Result<types::Value, String> {
        let now = match &env.now {
            types::Value::Time(t) => *t,
            other => return Err(format!("the scope now holds {other:?}, not a time")),
        };
        let principal = match &env.principal {
            types::Value::Str(id) => Some(id.clone()),
            types::Value::Null => None,
            other => {
                return Err(format!(
                    "the scope principal holds {other:?}, not a principal's id or null"
                ));
            }
        };

        struct Scopes<'a> {
            env: &'a types::RuleEnv,
            now: i64,
            principal: Option<String>,
        }

        impl crate::rule_language::Env for Scopes<'_> {
            fn record(&self, scope: &types::Scope) -> Option<&dyn crate::rule_language::Record> {
                let record = match scope {
                    types::Scope::Record => &self.env.record,
                    types::Scope::Old => &self.env.old,
                    types::Scope::New => &self.env.new,
                };
                record
                    .as_ref()
                    .map(|r| r as &dyn crate::rule_language::Record)
            }

            fn follow(
                &self,
                _scope: &types::Scope,
                _field: &str,
                _target: &u64,
            ) -> Result<
                Option<Box<dyn crate::rule_language::Record + '_>>,
                crate::rule_language::EvalError,
            > {
                Err(crate::rule_language::EvalError(
                    "following a reference needs a lookup, and none is available".to_string(),
                ))
            }

            fn param(&self, name: &str) -> Option<types::Value> {
                self.env.param.get(name).cloned()
            }

            fn now(&self) -> i64 {
                self.now
            }

            fn principal(&self) -> Option<String> {
                self.principal.clone()
            }

            fn has_role(&self, role: &str) -> bool {
                self.env.has_role.iter().any(|held| held == role)
            }
        }
        crate::rule_language::eval(
            expr,
            &Scopes {
                env,
                now,
                principal,
            },
        )
        .map_err(|e| e.0)
    }
    pub(super) fn eval_lookup_rule_language_rule_env(
        expr: &types::Expr,
        env: &types::RuleEnv,
        lookup: &std::collections::BTreeMap<
            String,
            std::collections::BTreeMap<String, std::collections::BTreeMap<String, types::Value>>,
        >,
    ) -> Result<types::Value, String> {
        let now = match &env.now {
            types::Value::Time(t) => *t,
            other => return Err(format!("the scope now holds {other:?}, not a time")),
        };
        let principal = match &env.principal {
            types::Value::Str(id) => Some(id.clone()),
            types::Value::Null => None,
            other => {
                return Err(format!(
                    "the scope principal holds {other:?}, not a principal's id or null"
                ));
            }
        };

        struct Scopes<'a> {
            env: &'a types::RuleEnv,
            lookup: &'a std::collections::BTreeMap<
                String,
                std::collections::BTreeMap<
                    String,
                    std::collections::BTreeMap<String, types::Value>,
                >,
            >,
            now: i64,
            principal: Option<String>,
        }

        impl crate::rule_language::Env for Scopes<'_> {
            fn record(&self, scope: &types::Scope) -> Option<&dyn crate::rule_language::Record> {
                let record = match scope {
                    types::Scope::Record => &self.env.record,
                    types::Scope::Old => &self.env.old,
                    types::Scope::New => &self.env.new,
                };
                record
                    .as_ref()
                    .map(|r| r as &dyn crate::rule_language::Record)
            }

            fn follow(
                &self,
                _scope: &types::Scope,
                field: &str,
                target: &u64,
            ) -> Result<
                Option<Box<dyn crate::rule_language::Record + '_>>,
                crate::rule_language::EvalError,
            > {
                let Some(covered) = self.lookup.get(field) else {
                    return Err(crate::rule_language::EvalError(format!(
                        "the lookup does not cover {field}"
                    )));
                };
                Ok(covered.get(&target.to_string()).map(|found| {
                    Box::new(found.clone()) as Box<dyn crate::rule_language::Record + '_>
                }))
            }

            fn param(&self, name: &str) -> Option<types::Value> {
                self.env.param.get(name).cloned()
            }

            fn now(&self) -> i64 {
                self.now
            }

            fn principal(&self) -> Option<String> {
                self.principal.clone()
            }

            fn has_role(&self, role: &str) -> bool {
                self.env.has_role.iter().any(|held| held == role)
            }
        }
        crate::rule_language::eval(
            expr,
            &Scopes {
                env,
                lookup,
                now,
                principal,
            },
        )
        .map_err(|e| e.0)
    }
}

