    /// Example 1 of `deny`.
    #[test]
    fn deny_example_1() {
        let acc: types::AuthState = types::AuthState {
            granted: None,
            checks: Vec::new(),
        };
        let rule: String = "policy:p".to_string();
        let want_: types::AuthState = types::AuthState {
            granted: None,
            checks: vec![types::RuleCheck {
                rule: "policy:p".to_string(),
                passed: false,
            }],
        };
        assert_eq!(deny(&acc, &rule), want_);
    }

    /// Example 1 of `policy-step`.
    #[test]
    fn policy_step_example_1() {
        let policy: types::PolicyDef = types::PolicyDef {
            id: "writers_read_notes".to_string(),
            role: "writer".to_string(),
            resource: types::Resource::Object("note".to_string()),
            actions: vec![types::Action::Read, types::Action::Create],
            condition: None,
        };
        let env: types::RuleEnv = types::RuleEnv {
            record: None,
            old: None,
            new: None,
            param: std::collections::BTreeMap::new(),
            now: types::Value::Time(5000),
            principal: types::Value::Str("alpha:writer1".to_string()),
            has_role: vec!["public".to_string(), "writer".to_string()],
        };
        let acc: types::AuthState = types::AuthState {
            granted: None,
            checks: Vec::new(),
        };
        let want_: types::AuthState = types::AuthState {
            granted: Some(types::RuleCheck {
                rule: "policy:writers_read_notes".to_string(),
                passed: true,
            }),
            checks: Vec::new(),
        };
        assert_eq!(policy_step(&policy, &env, &acc), want_);
    }

    /// Comparing a string with an int is an evaluation error, which fails the check.
